"""Read-only adjacent original prescriptions with fictional clinical overlays."""
from __future__ import annotations

from .exact_rx_teaching import SCHEMA, canonical, presentable
from .ui_tokens import TOKENS


def render_exact_rx(bundle: dict) -> str:
    if (bundle.get('schema_version') != SCHEMA or bundle.get('mode') not in
            ('original_rx_simulated_clinical', 'synthetic_software_fixture')
            or not bundle.get('episodes')):
        raise ValueError('EXACT_RX_BUNDLE_INVALID')
    payload = canonical(presentable(bundle)).decode('utf-8').replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return HTML.replace('__CSS__', CSS).replace('__DATA__', payload).replace('__JS__', JS)


